-- | The protocol compiler can output a FileDescriptorSet containing the .proto
-- files it parses.
data FileDescriptorSet = FileDescriptorSet
  { fileDescriptorSetFile :: !(V.Vector FileDescriptorProto)
  , fileDescriptorSetUnknownFields :: ![UnknownField]
  }
  deriving stock (Show, Eq, Generic)
  deriving anyclass NFData

defaultFileDescriptorSet :: FileDescriptorSet
defaultFileDescriptorSet = FileDescriptorSet
  { fileDescriptorSetFile = V.empty
  , fileDescriptorSetUnknownFields = []
  }

instance MessageEncode FileDescriptorSet where
  buildSized msg =
    V.foldl' (\acc v -> acc <> archSubmessage 10 (buildSized v)) mempty msg.fileDescriptorSetFile
    <> encodeUnknownFieldsSized msg.fileDescriptorSetUnknownFields

instance MessageDecode FileDescriptorSet where
  {-# INLINE messageDecoder #-}
  messageDecoder = stage_0 defaultFileDescriptorSet emptyGrowList
    where
      stage_0 msg gl_0 =
        inOrderStage1
          (0xa :: Data.Word.Word8)
          decodeFieldMessage
          (\v -> stage_0 msg (snocGrowList gl_0 v))
          (pure (case msg.fileDescriptorSetUnknownFields of { [] -> msg { fileDescriptorSetFile = growListToVector gl_0 }; _ -> msg { fileDescriptorSetFile = growListToVector gl_0, fileDescriptorSetUnknownFields = reverse (msg.fileDescriptorSetUnknownFields) } }))
          (loop msg gl_0)
      loop msg gl_0 = withTagM
        (pure (case msg.fileDescriptorSetUnknownFields of { [] -> msg { fileDescriptorSetFile = growListToVector gl_0 }; _ -> msg { fileDescriptorSetFile = growListToVector gl_0, fileDescriptorSetUnknownFields = reverse (msg.fileDescriptorSetUnknownFields) } }))
        (\fn wt -> case fn of
          1 -> do
            v <- decodeFieldMessage
            loop msg (snocGrowList gl_0 v)
          _ -> do
            uf <- captureUnknownField fn (Prelude.toEnum wt)
            loop (msg { fileDescriptorSetUnknownFields = (uf : msg.fileDescriptorSetUnknownFields)}) gl_0)

-- | Field descriptors for 'FileDescriptorSet', keyed by proto field number.
--
-- Top-level CAF: allocated lazily on first force, shared on every
-- subsequent 'protoFieldDescriptors' call (no per-call rebuild).
fileDescriptorSetFieldDescriptors :: IntMap.IntMap (SomeFieldDescriptor FileDescriptorSet)
fileDescriptorSetFieldDescriptors =
  IntMap.fromList
    [ (1, SomeField FieldDescriptor
        { fdName = "file"
        , fdNumber = 1
        , fdTypeDesc = MessageType "FileDescriptorProto"
        , fdLabel = LabelRepeated
        , fdGet = fileDescriptorSetFile
        , fdSet = \v m -> m { fileDescriptorSetFile = v }
        })
    ]

instance ProtoMessage FileDescriptorSet where
  protoMessageName _ = "google.protobuf.FileDescriptorSet"
  protoPackageName _ = "google.protobuf"
  protoDefaultValue = defaultFileDescriptorSet
  protoFileDescriptorBytes _ = fileDescriptorProtoBytes
  protoFieldDescriptors _ = fileDescriptorSetFieldDescriptors

instance IsMessage FileDescriptorSet

instance Aeson.ToJSON FileDescriptorSet where
  toJSON msg = jsonObject
      [ "file" .=: msg.fileDescriptorSetFile

      ]

instance Aeson.FromJSON FileDescriptorSet where
  parseJSON = Aeson.withObject "FileDescriptorSet" $ \obj -> do
    fld_fileDescriptorSetFile <- parseFieldMaybe obj "file"
    pure defaultFileDescriptorSet
      { fileDescriptorSetFile = maybe (fileDescriptorSetFile defaultFileDescriptorSet) id fld_fileDescriptorSetFile
      }

instance Hashable FileDescriptorSet where
  hashWithSalt salt msg = V.foldl' hashWithSalt (salt) msg.fileDescriptorSetFile

instance Proto.Extension.HasExtensions FileDescriptorSet where
  messageUnknownFields = fileDescriptorSetUnknownFields
  setMessageUnknownFields !ufs msg = msg { fileDescriptorSetUnknownFields = ufs }

instance Semigroup FileDescriptorSet where
  a <> b = FileDescriptorSet
    { fileDescriptorSetFile = a.fileDescriptorSetFile <> b.fileDescriptorSetFile
    , fileDescriptorSetUnknownFields = a.fileDescriptorSetUnknownFields <> b.fileDescriptorSetUnknownFields
    }

instance Monoid FileDescriptorSet where
  mempty = defaultFileDescriptorSet

-- | The full set of known editions.
data Edition
  = Edition'EditionUnknown
    -- ^ A placeholder for an unknown edition value.
  | Edition'EditionLegacy
    -- ^ A placeholder edition for specifying default behaviors *before* a feature
    -- was first introduced.  This is effectively an "infinite past".
  | Edition'EditionProto2
    -- ^ Legacy syntax "editions".  These pre-date editions, but behave much like
    -- distinct editions.  These can't be used to specify the edition of proto
    -- files, but feature definitions must supply proto2/proto3 defaults for
    -- backwards compatibility.
  | Edition'EditionProto3
  | Edition'Edition2023
    -- ^ Editions that have been released.  The specific values are arbitrary and
    -- should not be depended on, but they will always be time-ordered for easy
    -- comparison.
  | Edition'Edition2024
  | Edition'Edition1TestOnly
    -- ^ Placeholder editions for testing feature resolution.  These should not be
    -- used or relyed on outside of tests.
  | Edition'Edition2TestOnly
  | Edition'Edition99997TestOnly
  | Edition'Edition99998TestOnly
  | Edition'Edition99999TestOnly
  | Edition'EditionMax
    -- ^ Placeholder for specifying unbounded edition support.  This should only
    -- ever be used by plugins that can expect to never require any changes to
    -- support a new edition.
  deriving stock (Show, Eq, Ord, Prelude.Enum, Prelude.Bounded, Generic)
  deriving anyclass NFData

toProtoEnumEdition :: Edition -> Int
toProtoEnumEdition Edition'EditionUnknown = 0
toProtoEnumEdition Edition'EditionLegacy = 900
toProtoEnumEdition Edition'EditionProto2 = 998
toProtoEnumEdition Edition'EditionProto3 = 999
toProtoEnumEdition Edition'Edition2023 = 1000
toProtoEnumEdition Edition'Edition2024 = 1001
toProtoEnumEdition Edition'Edition1TestOnly = 1
toProtoEnumEdition Edition'Edition2TestOnly = 2
toProtoEnumEdition Edition'Edition99997TestOnly = 99997
